Part 2 — a deliberate heap overflow, read under ASan. Write this program, deliberately wrong:

```c
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    char *buf = malloc(16);
    if (buf == NULL)
        return 1;

    for (size_t i = 0; i < 20; i++)
        buf[i] = 'A';

    printf("wrote 20 bytes into a 16-byte block\n");
    free(buf);
    return 0;
}
```

Part 3 — a segfault, into the debugger. Write this program:

```c
#include <stdio.h>

static void scribble(char *dst, int n)
{
    for (int i = 0; i < n; i++)
        dst[i] = 'x';
}

static void middle(int n)
{
    char *target = NULL;
    int guard = 7;

    printf("about to write %d bytes\n", n);
    scribble(target, n);
    printf("guard is still %d\n", guard);
}

int main(void)
{
    middle(4);
    printf("survived\n");
    return 0;
}
```
